import{_ as e,o,c as a,a2 as d}from"./chunks/framework.ClgMjOt7.js";const g=JSON.parse('{"title":"閲覧 & 検索履歴仕様","description":"閲覧履歴、検索履歴の Room DB スキーマ、削除処理、シークレットモード","frontmatter":{"title":"閲覧 & 検索履歴仕様","description":"閲覧履歴、検索履歴の Room DB スキーマ、削除処理、シークレットモード"},"headers":[],"relativePath":"features/history.md","filePath":"features/history.md","lastUpdated":1786168778000}'),l={name:"features/history.md"};function i(r,t,c,s,n,h){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="閲覧-検索履歴仕様" tabindex="-1">閲覧 &amp; 検索履歴仕様 <a class="header-anchor" href="#閲覧-検索履歴仕様" aria-label="Permalink to &quot;閲覧 &amp; 検索履歴仕様&quot;">​</a></h1><p>閲覧および検索アクティビティの記録・保持・管理機能についての技術仕様です。</p><hr><h2 id="閲覧履歴-viewhistoryscreen" tabindex="-1">閲覧履歴 (<code>ViewHistoryScreen</code>) <a class="header-anchor" href="#閲覧履歴-viewhistoryscreen" aria-label="Permalink to &quot;閲覧履歴 (`ViewHistoryScreen`)&quot;">​</a></h2><p>過去に表示した作品（イラスト・マンガ・小説）の情報がローカル Room データベースに記録されます。</p><h3 id="データベース構造-viewhistoryentity" tabindex="-1">データベース構造 (<code>ViewHistoryEntity</code>) <a class="header-anchor" href="#データベース構造-viewhistoryentity" aria-label="Permalink to &quot;データベース構造 (`ViewHistoryEntity`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">カラム名</th><th style="text-align:left;">型</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>illustId</code></td><td style="text-align:left;"><code>Long</code> (PK)</td><td style="text-align:left;">作品 ID</td></tr><tr><td style="text-align:left;"><code>title</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;">作品タイトル</td></tr><tr><td style="text-align:left;"><code>userId</code></td><td style="text-align:left;"><code>Long</code></td><td style="text-align:left;">作者の Pixiv ID</td></tr><tr><td style="text-align:left;"><code>userName</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;">作者の表示名</td></tr><tr><td style="text-align:left;"><code>thumbnailUrl</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;">プレビューサムネイル画像 URL</td></tr><tr><td style="text-align:left;"><code>workType</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;">作品タイプ (<code>illust</code> / <code>manga</code> / <code>novel</code>)</td></tr><tr><td style="text-align:left;"><code>pageCount</code></td><td style="text-align:left;"><code>Int</code></td><td style="text-align:left;">ページ数</td></tr><tr><td style="text-align:left;"><code>viewedAt</code></td><td style="text-align:left;"><code>Long</code></td><td style="text-align:left;">最終閲覧日時タイムスタンプ</td></tr></tbody></table><h3 id="機能仕様" tabindex="-1">機能仕様 <a class="header-anchor" href="#機能仕様" aria-label="Permalink to &quot;機能仕様&quot;">​</a></h3><ul><li><strong>履歴内検索</strong>: 記録されたタイトルや作者名に対するリアルタイムフィルタリング。</li><li><strong>グループ表示</strong>: 閲覧日時に基づくグループ分け表示（「今日」「昨日」「今週」「以前」）。</li><li><strong>個別削除 / 一括削除</strong>: 選択項目の個別消去、または全閲覧履歴のデータクリア。</li></ul><hr><h2 id="検索履歴-searchhistoryentity" tabindex="-1">検索履歴 (<code>SearchHistoryEntity</code>) <a class="header-anchor" href="#検索履歴-searchhistoryentity" aria-label="Permalink to &quot;検索履歴 (`SearchHistoryEntity`)&quot;">​</a></h2><p>検索バーに入力されたキーワードおよび検索タグの履歴管理です。</p><h3 id="データベース構造-searchhistoryentity" tabindex="-1">データベース構造 (<code>SearchHistoryEntity</code>) <a class="header-anchor" href="#データベース構造-searchhistoryentity" aria-label="Permalink to &quot;データベース構造 (`SearchHistoryEntity`)&quot;">​</a></h3><ul><li><code>query</code> (<code>String</code>, PK): 検索キーワード・タグ文字列</li><li><code>searchedAt</code> (<code>Long</code>): 最終検索日時タイムスタンプ</li></ul><h3 id="機能仕様-1" tabindex="-1">機能仕様 <a class="header-anchor" href="#機能仕様-1" aria-label="Permalink to &quot;機能仕様&quot;">​</a></h3><ul><li>検索フォーム入力時のオートコンプリート（検索候補）表示。</li><li>各候補の末尾アイコンタップによる個別履歴の削除。</li></ul><hr><h2 id="記録制御-シークレットモード-appsettings" tabindex="-1">記録制御 &amp; シークレットモード (<code>AppSettings</code>) <a class="header-anchor" href="#記録制御-シークレットモード-appsettings" aria-label="Permalink to &quot;記録制御 &amp; シークレットモード (`AppSettings`)&quot;">​</a></h2><p>設定画面 (<code>DataSettingsScreen</code>) から記録の保存動作を変更できます。</p><ul><li><code>saveViewHistory</code> (<code>Boolean</code>): 閲覧履歴の自動記録設定 (デフォルト <code>true</code>)。</li><li><code>saveSearchHistory</code> (<code>Boolean</code>): 検索履歴の自動記録設定 (デフォルト <code>true</code>)。</li></ul><div class="info custom-block"><p class="custom-block-title">プライバシーの保護</p><p>両方のフラグを <code>false</code> に設定することで、一切のアクティビティログをデータベースへ書き込まないシークレットモードとして動作させることができます。</p></div>',21)])])}const f=e(l,[["render",i]]);export{g as __pageData,f as default};
